using KeyEventArgs = System.Windows.Input.KeyEventArgs;
using System.Windows.Interop;
using Microsoft.Toolkit.Uwp.Notifications;
using Forms = System.Windows.Forms;
namespace FluentSnap;
public partial class MainWindow : Wpf.Ui.Controls.FluentWindow
{
 CaptureMode mode; readonly UserSettings settings=SettingsStore.Load(); readonly ShortcutService shortcuts=new(); readonly Forms.NotifyIcon notification=new(){Icon=System.Drawing.SystemIcons.Application,Visible=false}; CaptureToolbar? toolbar; CaptureNotification? fallbackNotification; BitmapSource? pendingCapture; IntPtr handle; bool fullscreen; WindowState priorState; WindowStyle priorStyle; ResizeMode priorResize; double priorWidth,priorHeight,priorLeft,priorTop;
 public MainWindow(){InitializeComponent();var logo=System.IO.Path.Combine(AppContext.BaseDirectory,"logo.png");if(File.Exists(logo))BrandMark.Source=new BitmapImage(new Uri(logo));EnsureCaptureFolder();mode=settings.DefaultMode;ShortcutHint.Text=$"Press {settings.CaptureShortcut}";notification.BalloonTipClicked+=NotificationClicked;ToastNotificationManagerCompat.OnActivated+=ToastActivated;PreviewKeyDown+=MainWindow_PreviewKeyDown;SourceInitialized+=OnSourceInitialized;Closed+=OnClosed;WindowState=WindowState.Normal;ShowInTaskbar=true;}
 void TitleBar_MouseLeftButtonDown(object _,MouseButtonEventArgs e){if(e.OriginalSource is DependencyObject d&&FindButtonParent(d) is not null)return;if(e.ClickCount==2){Maximize_Click(_,e);return;}if(e.LeftButton==MouseButtonState.Pressed)DragMove();} static Button? FindButtonParent(DependencyObject d){while(d is not null){if(d is Button b)return b;d=VisualTreeHelper.GetParent(d);}return null;}
 void OnSourceInitialized(object? _,EventArgs e){handle=new WindowInteropHelper(this).Handle;shortcuts.Initialize(this);shortcuts.CapturePressed+=ShortcutPressed;if(!shortcuts.RegisterCapture(settings.CaptureShortcut,out var error))StatusText.Text=$"Shortcut unavailable: {error}";}
 void ShortcutPressed(object? _,EventArgs e)=>Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>{if(settings.OpenToolbarOnShortcut)ShowToolbar();else StartCapture(true);}));
 void MainWindow_PreviewKeyDown(object _,KeyEventArgs e){if(e.Key==Key.Escape&&fullscreen){ExitFullscreen();e.Handled=true;}}
 void StartCapture(bool fromShortcut=false){toolbar?.Close();toolbar=null;fallbackNotification?.Close();fallbackNotification=null;notification.Visible=false;if(!IsVisible)return;Hide();Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>{try{Log("Capture requested");var o=new CaptureOverlay(mode);o.ShowDialog();if(o.Result is not null){pendingCapture=o.Result;Log($"Capture completed: {o.Result.PixelWidth}x{o.Result.PixelHeight} {o.Result.Format}");ShowImage(o.Result);SaveCaptureToFolder(o.Result);}}catch(Exception ex){Log($"Capture failed: {ex}");System.Windows.MessageBox.Show(ex.Message,"Capture failed",MessageBoxButton.OK,MessageBoxImage.Error);}finally{if(settings.RestoreAfterCapture){Show();Activate();}}}));}
 string? lastSavedFile;
 void EnsureCaptureFolder(){var folder=string.IsNullOrWhiteSpace(settings.CaptureFolder)?System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyPictures),"Screenshoots"):settings.CaptureFolder;try{Directory.CreateDirectory(folder);settings.CaptureFolder=folder;Log($"Capture folder ready: {folder}");}catch(Exception ex){Log($"Capture folder unavailable: {folder}; {ex}");}}
 void SaveCaptureToFolder(BitmapSource image){var requested=string.IsNullOrWhiteSpace(settings.CaptureFolder)?System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyPictures),"Screenshoots"):settings.CaptureFolder;var fallback=System.IO.Path.Combine(SettingsStore.Folder,"Captures");Exception? last=null;lastSavedFile=null;var frozen=image.CanFreeze?image.Clone():image;if(frozen.CanFreeze&&!frozen.IsFrozen)frozen.Freeze();foreach(var folder in new[]{requested,fallback}.Distinct(StringComparer.OrdinalIgnoreCase)){try{Directory.CreateDirectory(folder);var file=System.IO.Path.Combine(folder,$"{DateTime.Now:yyyy-MM-dd_HH-mm-ss-fff}.png");using(var stream=new FileStream(file,FileMode.CreateNew,FileAccess.Write,FileShare.Read)){var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(frozen));encoder.Save(stream);stream.Flush(true);}if(!File.Exists(file)||new FileInfo(file).Length==0)throw new IOException("The saved file was empty.");lastSavedFile=file;break;}catch(Exception ex){last=ex;Log($"Save attempt failed in {folder}: {ex}");}}if(lastSavedFile is null){StatusText.Text=$"Could not save capture: {last?.Message}";CaptureLocationText.Text="Screenshot save failed";ShowCaptureNotification($"Save failed: {last?.Message}");return;}CaptureLocationText.Text=lastSavedFile;CaptureLocationText.ToolTip=lastSavedFile;try{Clipboard.SetImage(frozen);StatusText.Text=$"Saved and copied: {lastSavedFile}";}catch(Exception ex){StatusText.Text=$"Saved: {lastSavedFile}; clipboard unavailable: {ex.Message}";}Log($"Save verified: {lastSavedFile} ({new FileInfo(lastSavedFile).Length} bytes)");ShowCaptureNotification($"Screenshot saved: {lastSavedFile}");}
 void OpenLatestCapture(){try{if(pendingCapture is not null){ShowImage(pendingCapture);}else{var folder=Directory.Exists(settings.CaptureFolder)?settings.CaptureFolder:System.IO.Path.Combine(SettingsStore.Folder,"Captures");var latest=Directory.Exists(folder)?Directory.GetFiles(folder,"*.png").OrderByDescending(File.GetLastWriteTimeUtc).FirstOrDefault():null;if(latest is not null)ShowImage(ImageLoader.Load(latest));}Show();Activate();}catch(Exception ex){StatusText.Text=$"Could not open latest capture: {ex.Message}";}}
 void ShowCaptureNotification(string? detail=null){var message=detail??(lastSavedFile is null?"Screenshot captured":"Saved: "+lastSavedFile);var logo=System.IO.Path.Combine(AppContext.BaseDirectory,"logo.png");try{var toast=new ToastContentBuilder().AddArgument("action","open").AddText("FluentSnap").AddText(message);if(File.Exists(logo))toast.AddAppLogoOverride(new Uri(logo));toast.Show();Log($"Windows toast requested: {message}");}catch(Exception ex){Log($"Windows toast failed: {ex}");StatusText.Text=$"Notification unavailable: {ex.Message}";}fallbackNotification?.Close();fallbackNotification=new CaptureNotification(OpenLatestCapture,message);fallbackNotification.Closed+=(_,_)=>fallbackNotification=null;fallbackNotification.Show();}
 void Log(string message){try{Directory.CreateDirectory(SettingsStore.Folder);File.AppendAllText(System.IO.Path.Combine(SettingsStore.Folder,"capture.log"),$"{DateTime.Now:O} {message}{Environment.NewLine}");}catch{}}
 void NotificationClicked(object? _,EventArgs __){Dispatcher.BeginInvoke(new Action(()=>{notification.Visible=false;fallbackNotification?.Close();fallbackNotification=null;OpenLatestCapture();}));}
 void ToastActivated(ToastNotificationActivatedEventArgsCompat _)=>Dispatcher.BeginInvoke(new Action(OpenLatestCapture));
 void GitHub_Click(object s,RoutedEventArgs e){try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("https://github.com/ndaju/fluentsnap"){UseShellExecute=true});}catch(Exception ex){StatusText.Text=$"Could not open GitHub: {ex.Message}";}}
 void RegisterStartup(){try{using var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Run",true);if(key is null){StatusText.Text="Windows startup registration unavailable";return;}key.SetValue("FluentSnap",Environment.ProcessPath??"");}catch(Exception ex){StatusText.Text=$"Startup registration unavailable: {ex.Message}";} }
 void ShowToolbar(){if(toolbar is not null){toolbar.Activate();return;}toolbar=new CaptureToolbar(mode,m=>{SetMode(m);StartCapture(true);});toolbar.Closed+=(_,_)=>toolbar=null;toolbar.Show();}
 void SetMode(CaptureMode value){mode=value;if(settings.RememberLastMode){settings.DefaultMode=value;settings.LastMode=value.ToString();SettingsStore.Save(settings,out _);}}
 void Settings_Click(object s,RoutedEventArgs e){var dialog=new SettingsWindow(settings);if(dialog.ShowDialog()!=true||dialog.Result is null)return;var updated=dialog.Result;if(!shortcuts.RegisterCapture(updated.CaptureShortcut,out var error)){StatusText.Text=$"Shortcut unavailable: {error}";return;}if(!SettingsStore.Save(updated,out error)){shortcuts.RegisterCapture(settings.CaptureShortcut,out _);StatusText.Text=$"Could not save settings: {error}";return;}settings.CaptureShortcut=updated.CaptureShortcut;settings.DefaultMode=updated.DefaultMode;settings.OpenToolbarOnShortcut=updated.OpenToolbarOnShortcut;settings.RememberLastMode=updated.RememberLastMode;settings.ShowTooltips=updated.ShowTooltips;settings.RestoreAfterCapture=updated.RestoreAfterCapture;settings.StartMinimized=updated.StartMinimized;settings.CaptureFolder=updated.CaptureFolder;ShortcutHint.Text=$"Press {settings.CaptureShortcut}";mode=settings.DefaultMode;StatusText.Text=$"Shortcut registered: {settings.CaptureShortcut}";}
 void Close_Click(object s,RoutedEventArgs e)=>Close(); void Minimize_Click(object s,RoutedEventArgs e)=>WindowState=WindowState.Minimized;
 void Maximize_Click(object s,RoutedEventArgs e)=>WindowState=WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized;
 void Fullscreen_Click(object s,RoutedEventArgs e){if(fullscreen)ExitFullscreen();else EnterFullscreen();}
 void EnterFullscreen(){if(fullscreen)return;priorState=WindowState;priorStyle=WindowStyle;priorResize=ResizeMode;priorWidth=Width;priorHeight=Height;priorLeft=Left;priorTop=Top;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;WindowState=WindowState.Maximized;TitleBar.Visibility=Visibility.Collapsed;TitleRow.Height=new GridLength(0);fullscreen=true;StatusText.Text="Fullscreen mode · press Escape or the fullscreen button to restore";}
 void ExitFullscreen(){if(!fullscreen)return;WindowState=WindowState.Normal;WindowStyle=priorStyle;ResizeMode=priorResize;Width=priorWidth;Height=priorHeight;Left=priorLeft;Top=priorTop;WindowState=priorState==WindowState.Minimized?WindowState.Normal:priorState;TitleBar.Visibility=Visibility.Visible;TitleRow.Height=new GridLength(58);fullscreen=false;StatusText.Text="Ready";}
 void Open_Click(object s,RoutedEventArgs e){var d=new Microsoft.Win32.OpenFileDialog{Filter="Images|*.png;*.jpg;*.jpeg;*.bmp"};try{if(d.ShowDialog()==true)ShowImage(ImageLoader.Load(d.FileName));}catch(Exception ex){System.Windows.MessageBox.Show(ex.Message,"Could not open image",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void Save_Click(object s,RoutedEventArgs e){if(!Editor.HasImage)return;var d=new Microsoft.Win32.SaveFileDialog{Filter="PNG image|*.png",FileName="FluentSnap.png"};try{if(d.ShowDialog()==true){Editor.Save(d.FileName);StatusText.Text=$"Saved {System.IO.Path.GetFileName(d.FileName)}";}}catch(Exception ex){System.Windows.MessageBox.Show(ex.Message,"Could not save image",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void ShowImage(BitmapSource i){Editor.SetImage(i);Editor.Visibility=Visibility.Visible;EmptyState.Visibility=Visibility.Collapsed;EditorTools.Visibility=Visibility.Visible;StatusText.Text=$"{i.PixelWidth} × {i.PixelHeight}";}
 void Copy_Click(object s,RoutedEventArgs e){try{if(Editor.HasImage){Clipboard.SetImage(Editor.RenderImage());StatusText.Text="Copied image to clipboard";}}catch(Exception ex){System.Windows.MessageBox.Show(ex.Message,"Could not copy image",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void Pen_Click(object s,RoutedEventArgs e)=>Editor.Tool=EditorTool.Pen;void Highlighter_Click(object s,RoutedEventArgs e)=>Editor.Tool=EditorTool.Highlighter;void Crop_Click(object s,RoutedEventArgs e){Editor.Tool=EditorTool.Crop;StatusText.Text="Drag a crop rectangle to apply it.";}void Undo_Click(object s,RoutedEventArgs e)=>Editor.Undo();void Redo_Click(object s,RoutedEventArgs e)=>Editor.Redo();void Fit_Click(object s,RoutedEventArgs e)=>Editor.Fit();void More_Click(object s,RoutedEventArgs e)=>Editor.ClearAnnotations();
 void OnClosed(object? _,EventArgs e){ToastNotificationManagerCompat.OnActivated-=ToastActivated;notification.Visible=false;notification.Dispose();fallbackNotification?.Close();toolbar?.Close();shortcuts.Dispose();}
}
